import { useState } from "react";
import { Modal } from "react-bootstrap";

const money = (value) =>
  new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR" }).format(
    value,
  );

/** Collects the customer fields required by OrderRequest; dates are generated by the backend. */
export default function CheckoutPopup({
  show,
  handleClose,
  cartItems,
  totalPrice,
  handleCheckout,
  submitting,
  error,
}) {
  const [customerName, setCustomerName] = useState("");
  const [email, setEmail] = useState("");
  return (
    <Modal
      show={show}
      onHide={handleClose}
      backdrop={submitting ? "static" : true}
      keyboard={!submitting}
      centered
      contentClassName="order-checkout"
    >
      <Modal.Header closeButton={!submitting}>
        <Modal.Title>Make it yours.</Modal.Title>
      </Modal.Header>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (customerName.trim() && email.trim())
            handleCheckout({ customerName, email });
        }}
      >
        <Modal.Body>
          <p className="checkout-intro">A few details for your order.</p>
          <label className="checkout-field">
            Full name
            <input
              autoComplete="name"
              name="customerName"
              required
              maxLength={255}
              pattern=".*\S.*"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              disabled={submitting}
              placeholder="Your full name"
            />
          </label>
          <label className="checkout-field">
            Email address
            <input
              autoComplete="email"
              name="email"
              type="email"
              required
              maxLength={255}
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              disabled={submitting}
              placeholder="you@example.com"
            />
          </label>
          <div className="checkout-review">
            <h3>Your order</h3>
            {cartItems.map((item) => (
              <div key={item.id}>
                <span>
                  {item.name} <small>× {item.quantity}</small>
                </span>
                <strong>{money(item.price * item.quantity)}</strong>
              </div>
            ))}
            <div className="checkout-total">
              <span>Total</span>
              <strong>{money(totalPrice)}</strong>
            </div>
          </div>
          <p className="checkout-note">
            The store assigns the order date and order ID automatically. No
            payment is collected.
          </p>
          {error && (
            <p className="commerce-error" role="alert">
              {error}
            </p>
          )}
        </Modal.Body>
        <Modal.Footer>
          <button
            type="button"
            className="checkout-back"
            disabled={submitting}
            onClick={handleClose}
          >
            Back to bag
          </button>
          <button type="submit" className="shop-cta" disabled={submitting}>
            {submitting ? "Placing order…" : "Place order"}
          </button>
        </Modal.Footer>
      </form>
    </Modal>
  );
}
